import CardIcon from "./CardIcon";
import { dreadRange } from "../util/cardCatalog";

const DREAD_BAND_COLOR = [
    "from-emerald-500/20 to-emerald-700/5",   // DISQUIET
    "from-yellow-500/20 to-yellow-700/5",     // DISTRESS
    "from-orange-500/20 to-orange-700/5",     // DISMAY
    "from-rose-500/20 to-rose-700/5",         // DESPERATION
    "from-red-600/20 to-red-800/5",           // DISASTER
    "from-fuchsia-600/20 to-purple-800/5",    // DOOM
];

function SectionBlock({ section }) {
    const range = dreadRange(section.label);
    const accent = range ? DREAD_BAND_COLOR[range.end] : "from-slate-500/10 to-slate-700/5";
    return (
        <div className={`rounded-lg bg-gradient-to-br ${accent} ring-1 ring-white/10 p-4`}>
            <div className="flex items-center justify-between gap-3 mb-2">
                <div>
                    <span className="text-[11px] font-mono tracking-widest text-slate-300/70 uppercase">
                        {section.label}
                    </span>
                    {section.label_ko && (
                        <div className="text-sm font-semibold text-white">
                            {section.label_ko}
                        </div>
                    )}
                </div>
            </div>
            <p className="whitespace-pre-wrap text-sm leading-relaxed text-slate-100">
                {section.text_ko}
            </p>
        </div>
    );
}

export default function CardView({ card, onClose }) {
    if (!card) return null;
    const leftIcons = card.footer?.left || [];
    const rightIcons = card.footer?.right || [];

    return (
        <div className="relative flex flex-col h-full gap-4 overflow-hidden rounded-2xl border border-white/10 bg-gradient-to-br from-[#140414] via-[#0d0416] to-[#080015] shadow-2xl">
            {/* 헤더 */}
            <div className="relative px-6 pt-5 pb-4 border-b border-white/10">
                <div className="flex items-start justify-between gap-4">
                    <div className="min-w-0">
                        <div className="text-[10px] font-mono tracking-widest text-rose-400/80 uppercase mb-1">
                            #{String(card.globalId || card.id).padStart(3, "0")} · {card.setName_ko}
                        </div>
                        <h2 className="text-2xl font-bold text-white break-keep">
                            {card.card_ko}
                        </h2>
                        <div className="mt-1 text-xs text-slate-400">
                            {card.card}
                        </div>
                    </div>
                    {onClose && (
                        <button
                            onClick={onClose}
                            className="shrink-0 rounded-lg px-2 py-1 text-xs text-slate-300 ring-1 ring-white/10 hover:bg-white/5"
                        >
                            닫기
                        </button>
                    )}
                </div>

                <div className="flex flex-wrap items-center gap-2 mt-3">
                    {card.type_ko && (
                        <span className="inline-flex items-center rounded-full bg-white/5 px-2.5 py-1 text-xs font-medium text-rose-200 ring-1 ring-rose-400/30">
                            {card.type_ko}
                        </span>
                    )}
                    {(card.tags || []).map(tag => (
                        <span
                            key={tag}
                            className="inline-flex items-center rounded-full bg-white/[0.03] px-2 py-0.5 text-[10px] font-medium text-slate-400 ring-1 ring-white/10"
                        >
                            {tag}
                        </span>
                    ))}
                </div>
            </div>

            {/* 섹션 리스트 */}
            <div className="flex-1 min-h-0 overflow-y-auto px-6 pb-4 space-y-3">
                {(card.sections || []).map((s, i) => (
                    <SectionBlock key={i} section={s} />
                ))}
            </div>

            {/* 하단 아이콘 */}
            {(leftIcons.length > 0 || rightIcons.length > 0) && (
                <div className="flex items-center justify-between gap-2 px-6 py-3 border-t border-white/10 bg-white/[0.02]">
                    <div className="flex items-center gap-2">
                        {leftIcons.map((t, i) => (
                            <CardIcon key={`l${i}`} name={t.name} size={22} />
                        ))}
                    </div>
                    <div className="flex items-center gap-2">
                        {rightIcons.map((t, i) => (
                            <CardIcon key={`r${i}`} name={t.name} size={22} />
                        ))}
                    </div>
                </div>
            )}
        </div>
    );
}
