import iconsData from "../resource/dataSet/icons.json";

// webpack require.context로 아이콘 폴더 전체를 한 번에 import
const iconReq = require.context("../resource/icons", false, /\.(png|svg|jpg|jpeg)$/);

// icons.json의 asset 경로에서 파일명만 추출해 미리 URL 매핑
const iconUrls = (() => {
    const map = {};
    for (const [name, def] of Object.entries(iconsData)) {
        if (!def?.asset) continue;
        const filename = def.asset.split("/").pop();
        try {
            const url = iconReq("./" + filename);
            map[name] = url;
            for (const alias of def.aliases || []) {
                map[alias] = url;
            }
        } catch (e) {
            // 아이콘 파일이 로컬에 없으면 조용히 무시
        }
    }
    return map;
})();

export default function CardIcon({ name, size = 18, className = "" }) {
    if (!name) return null;
    const src = iconUrls[name] || iconUrls[String(name).toLowerCase()];
    if (!src) {
        // 매핑 실패 시 placeholder
        return (
            <span
                className={`inline-flex items-center justify-center rounded px-1 text-[10px] font-semibold text-slate-400 ring-1 ring-slate-600 ${className}`}
                style={{ height: size, minWidth: size }}
                title={name}
            >
                {name}
            </span>
        );
    }
    return (
        <img
            src={src}
            alt={name}
            title={name}
            className={`inline-block align-middle ${className}`}
            style={{ height: size, width: "auto" }}
        />
    );
}
