import { Component } from "react";
import { Search, Filter, X } from "lucide-react";
import { maladumSets } from "../resource/dataSet/setMeta";
import { allCards, allTypes, filterCards } from "../util/cardCatalog";
import CardIcon from "./CardIcon";
import CardView from "./CardView";

class CardBrowser extends Component {

    state = {
        setId: "base-game",
        type: "",
        query: "",
        selectedCard: null,
    }

    handler = {
        selectSet: (id) => this.setState({ setId: id, type: "", selectedCard: null }),
        selectType: (t) => this.setState({ type: t }),
        changeQuery: (e) => this.setState({ query: e.target.value }),
        clearQuery: () => this.setState({ query: "" }),
        openCard: (c) => this.setState({ selectedCard: c }),
        closeCard: () => this.setState({ selectedCard: null }),
    }

    render() {
        const { setId, type, query, selectedCard } = this.state;

        const cards = allCards();
        const filtered = filterCards(cards, { setId, type, query });
        const types = allTypes(cards.filter(c => c.setId === setId));
        const activeSet = maladumSets.find(s => s.id === setId);

        return (
            <div className="grid grid-cols-12 gap-5 min-h-[80vh]">
                {/* 좌측: 세트 & 필터 */}
                <aside className="col-span-3 flex flex-col gap-4">
                    <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                        <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                            <Filter className="w-3.5 h-3.5" /> 컨텐츠 세트
                        </div>
                        <div className="flex flex-col gap-1.5">
                            {maladumSets.map(s => (
                                <button
                                    key={s.id}
                                    onClick={() => this.handler.selectSet(s.id)}
                                    className={`group flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-left transition-colors ${
                                        s.id === setId
                                            ? "bg-gradient-to-r " + s.accent + " text-white shadow-md"
                                            : "bg-white/[0.02] text-slate-300 hover:bg-white/[0.06]"
                                    }`}
                                >
                                    <div className="min-w-0">
                                        <div className="text-sm font-semibold truncate">{s.name_ko}</div>
                                        <div className="text-[10px] opacity-70 truncate">{s.name}</div>
                                    </div>
                                    <span className={`text-xs tabular-nums ${s.id === setId ? "text-white" : "text-slate-500"}`}>
                                        {s.data.cards.length}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                        <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                            카드 유형
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            <button
                                onClick={() => this.handler.selectType("")}
                                className={`rounded-full px-2.5 py-1 text-xs ${
                                    type === ""
                                        ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/50"
                                        : "bg-white/[0.03] text-slate-400 ring-1 ring-white/10 hover:bg-white/[0.08]"
                                }`}
                            >
                                전체
                            </button>
                            {types.map(t => (
                                <button
                                    key={t}
                                    onClick={() => this.handler.selectType(t)}
                                    className={`rounded-full px-2.5 py-1 text-xs ${
                                        type === t
                                            ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/50"
                                            : "bg-white/[0.03] text-slate-400 ring-1 ring-white/10 hover:bg-white/[0.08]"
                                    }`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                </aside>

                {/* 중앙: 카드 그리드 */}
                <section className="col-span-5">
                    <div className="mb-4 flex items-center justify-between gap-3">
                        <div>
                            <div className="text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                                {activeSet?.name_ko_full}
                            </div>
                            <div className="mt-0.5 text-sm text-slate-300">
                                <span className="text-white font-semibold">{filtered.length}</span>
                                <span className="text-slate-500"> / {activeSet?.data.cards.length}장</span>
                            </div>
                        </div>
                        <div className="relative w-64">
                            <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-500 pointer-events-none" />
                            <input
                                type="text"
                                value={query}
                                onChange={this.handler.changeQuery}
                                placeholder="카드 검색..."
                                className="w-full rounded-lg bg-white/[0.04] px-9 py-2 text-sm text-white placeholder:text-slate-500 ring-1 ring-white/10 outline-none focus:ring-rose-400/40"
                            />
                            {query && (
                                <button
                                    onClick={this.handler.clearQuery}
                                    className="absolute right-2 top-2 rounded p-1 text-slate-400 hover:bg-white/5"
                                >
                                    <X className="w-3.5 h-3.5" />
                                </button>
                            )}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3 lg:grid-cols-3">
                        {filtered.map(c => {
                            const isActive = selectedCard?.globalId === c.globalId && selectedCard?.setId === c.setId;
                            return (
                                <button
                                    key={`${c.setId}-${c.globalId}`}
                                    onClick={() => this.handler.openCard(c)}
                                    className={`group text-left rounded-xl border p-3 transition-all ${
                                        isActive
                                            ? "border-rose-400/70 bg-rose-500/10 shadow-lg shadow-rose-500/10"
                                            : "border-white/10 bg-white/[0.02] hover:border-rose-400/40 hover:bg-white/[0.04]"
                                    }`}
                                >
                                    <div className="flex items-center justify-between gap-2 mb-2">
                                        <span className="text-[10px] font-mono tracking-widest text-slate-500">
                                            #{String(c.globalId || c.id).padStart(3, "0")}
                                        </span>
                                        <div className="flex items-center gap-1">
                                            {(c.footer?.left || []).slice(0, 2).map((t, i) => (
                                                <CardIcon key={i} name={t.name} size={14} />
                                            ))}
                                        </div>
                                    </div>
                                    <div className="text-sm font-semibold text-white leading-tight break-keep">
                                        {c.card_ko}
                                    </div>
                                    <div className="mt-1 text-[11px] text-slate-500 truncate">
                                        {c.type_ko}
                                    </div>
                                </button>
                            );
                        })}
                        {filtered.length === 0 && (
                            <div className="col-span-full py-16 text-center text-sm text-slate-500">
                                조건에 맞는 카드가 없습니다.
                            </div>
                        )}
                    </div>
                </section>

                {/* 우측: 카드 상세 */}
                <aside className="col-span-4">
                    <div className="sticky top-4 h-[82vh]">
                        {selectedCard ? (
                            <CardView card={selectedCard} onClose={this.handler.closeCard} />
                        ) : (
                            <div className="flex h-full flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/[0.02] text-center p-8">
                                <div className="mb-3 text-3xl">🃏</div>
                                <p className="text-sm text-slate-400">왼쪽에서 카드를 선택하세요</p>
                                <p className="mt-2 text-xs text-slate-600">각 카드의 공포 단계별 효과를 확인할 수 있습니다</p>
                            </div>
                        )}
                    </div>
                </aside>
            </div>
        );
    }
}

export default CardBrowser;
